using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.LungwortLichen;

/// <summary>
/// Lungwort lichen, broad green lobes over the fallen logs of the old, wet forest in the Mistlands, once taken for
/// sickness of the lungs. Model: generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class LungwortLichen : ForageableBase
{
    /// <summary>
    /// Prefab name of the lungwort lichen item.
    /// </summary>
    public const string PrefabName = "WhiteHiltLungwortLichen";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Lungwort Lichen";

    /// <inheritdoc/>
    protected override string Description => "Broad, ribbed green lobes peeled from a fallen log in the wet old forest. Healers gave it for the breath.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 20f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "lungwortitem" : "lungwort", 0.22f);
    }
}
